def rows(r):
    while True:
        a = "".join(r.choice("RY") for _ in range(7))
        b = "".join(r.choice("RY") for _ in range(7))
        if "RRRR" in a or "YYYY" in a or "RRRR" in b or "YYYY" in b:
            continue
        f = 0
        for j in range(7):
            c = b[j]
            nb = [a[j]] + ([b[j - 1]] if j else []) + ([b[j + 1]] if j < 6 else [])
            if all(x != c for x in nb):
                f += 1
        if f <= 3:
            return a, b


def generate(seed):
    r = random.Random(seed)
    a, b = rows(r)
    return a + " " + b + " " + str(r.randint(4, 11))

