LINES = []
NBR = []
for i in range(6):
    for j in range(7):
        for a, b in ((0, 1), (1, 0), (1, 1), (1, -1)):
            if 0 <= i + 3 * a < 6 and 0 <= j + 3 * b < 7:
                LINES.append(tuple((i + a * u) * 7 + (j + b * u) for u in range(4)))
        NBR.append(tuple((i + a) * 7 + j + b for a, b in ((0, 1), (0, -1), (1, 0), (-1, 0))
                         if 0 <= i + a < 6 and 0 <= j + b < 7))


def cost(t, k):
    f = sum(1 for L in LINES if t[L[0]] == t[L[1]] == t[L[2]] == t[L[3]])
    n = sum(1 for i in range(42) if all(t[j] != t[i] for j in NBR[i]))
    return 4 * f + abs(n - k)


def seed_free(r, k, nR):
    if k <= 5:
        free = []
        for i in range(14):
            ch = r.choice("RY")
            free += [ch, ch]
    elif k >= 9:
        o = r.randrange(2)
        free = ["RY"[(i // 7 + i % 7 + o) % 2] for i in range(28)]
    else:
        free = [r.choice("RY") for _ in range(28)]
    while free.count("R") > nR:
        i = r.randrange(28)
        if free[i] == "R":
            free[i] = "Y"
    while free.count("R") < nR:
        i = r.randrange(28)
        if free[i] == "Y":
            free[i] = "R"
    return free


def render(t):
    out = ["+-------------+"]
    for i in range(6):
        out.append("|" + " ".join(t[i * 7:i * 7 + 7]) + "|")
    out.append("+=============+")
    return "\n".join(out)


def solve(clue):
    a, b, ks = clue.split()
    k = int(ks)
    r = random.Random(clue)
    fix = list(a + b)
    nR = 21 - fix.count("R")
    for _ in range(14):
        t = seed_free(r, k, nR) + fix
        cur = cost(t, k)
        for it in range(6000):
            if cur == 0:
                return render(t)
            p = r.randrange(28)
            q = r.randrange(28)
            if t[p] == t[q]:
                continue
            t[p], t[q] = t[q], t[p]
            new = cost(t, k)
            if new <= cur or r.random() < 0.02:
                cur = new
            else:
                t[p], t[q] = t[q], t[p]
    return ""

